import { Component, Input, Output, EventEmitter } from '@angular/core';
import { trigger, transition, style, animate } from '@angular/animations';

export interface DropdownItem {
  label: string;
  icon?: string; // name in app-icon
  iconClass?: string;
  action: () => void;
  style?: any;
}

@Component({
  selector: 'app-dropdown-menu',
  template: `
    <div class="relative inline-block text-left" (clickOutside)="close()">
      <div (click)="toggle($event)">
        <ng-content select="[trigger]"></ng-content>
      </div>

      <div *ngIf="isOpen" 
           [@dropdownAnimation]
           class="absolute right-0 mt-2 w-56 origin-top-right bg-white border border-[#262626] rounded-[4px] shadow-2xl z-50 ring-1 ring-black ring-opacity-5 focus:outline-none backdrop-blur-sm"
           [style.min-width.px]="minWidth">
        <div role="menu" aria-orientation="vertical">
          <ng-content select="[items]"></ng-content>
        </div>
      </div>
    </div>
  `,
  styles: [],
  animations: [
    trigger('dropdownAnimation', [
      transition(':enter', [
        style({
          opacity: 0,
          transform: 'scale(0.95) translateY(-10px)'
        }),
        animate('200ms cubic-bezier(0.34, 1.56, 0.64, 1)',
          style({
            opacity: 1,
            transform: 'scale(1) translateY(0)'
          })
        )
      ]),
      transition(':leave', [
        animate('150ms ease-in',
          style({
            opacity: 0,
            transform: 'scale(0.95) translateY(-5px)'
          })
        )
      ])
    ])
  ]
})
export class DropdownMenuComponent {
  @Input() minWidth: number = 150;
  isOpen = false;

  private static currentOpenMenu: DropdownMenuComponent | null = null;

  toggle(event: Event) {
    event.stopPropagation();

    if (!this.isOpen) {
      // Opening
      if (DropdownMenuComponent.currentOpenMenu && DropdownMenuComponent.currentOpenMenu !== this) {
        DropdownMenuComponent.currentOpenMenu.isOpen = false;
      }
      DropdownMenuComponent.currentOpenMenu = this;
      this.isOpen = true;
    } else {
      // Closing
      this.isOpen = false;
      if (DropdownMenuComponent.currentOpenMenu === this) {
        DropdownMenuComponent.currentOpenMenu = null;
      }
    }
  }

  close() {
    this.isOpen = false;
    if (DropdownMenuComponent.currentOpenMenu === this) {
      DropdownMenuComponent.currentOpenMenu = null;
    }
  }
}
